-- with no row here is harmless, a row here with no R2 object is a broken image.

INSERT INTO photos (id, record_id, r2_key, sha256, bytes, content_type, is_primary, added_at, source) VALUES ('img_e_574a2bd0e164ac94', 'ehive_1831724', 'photos/ehive_1831724/img_e_574a2bd0e164ac94.jpg', '574a2bd0e164ac9413bc0f9eaf8edc905aacc2435a5dca30136e63aee32eaf5e', 223780, 'image/jpeg', 1, datetime('now'), 'ehive') ON CONFLICT(id) DO UPDATE SET r2_key=excluded.r2_key, sha256=excluded.sha256, bytes=excluded.bytes, source=excluded.source;
